func (a *HTTPAdapter) fail(w http.ResponseWriter, r *http.Request, err *httpserver.HandlerError) {
	// A response that failed to write leaves its media type, which is not the error's.
	w.Header().Del("Content-Type")
	a.opts.ErrorHandler.HandleError(w, r, err.StatusCode(), err)
}

func (a *HTTPAdapter) failDecode(w http.ResponseWriter, r *http.Request, id string, err error) {
	a.fail(w, r, &httpserver.HandlerError{Kind: httpserver.ErrorDecode, OperationID: id, Err: err})
}

func (a *HTTPAdapter) write(w http.ResponseWriter, r *http.Request, id string, res responseData) {
	if res.ContentType() != "" {
		w.Header().Set("Content-Type", res.ContentType())
	}
	err := httpserver.Write(w, res.StatusCode(), res.Header(), res.Payload())
	switch {
	case errors.Is(err, runtime.ErrContentType):
		a.fail(w, r, &httpserver.HandlerError{Kind: httpserver.ErrorResponse, OperationID: id, Err: err})
	case err != nil:
		a.fail(w, r, &httpserver.HandlerError{Kind: httpserver.ErrorService, OperationID: id, Err: err})
	}
}

// WithRouter registers the routes on app instead of a new App.
func WithRouter(app *fiber.App) ServerOption {
	return func(o *ServerOptions) {
		o.Router = app
	}
}

// WithConfig makes the new App with cfg.
func WithConfig(cfg fiber.Config) ServerOption {
	return func(o *ServerOptions) {
		o.Router = cfg
	}
}

// NewRouter registers every operation on a fiber App.
func NewRouter(svc ServiceInterface, opts ...ServerOption) *fiber.App {
	o := NewServerOptions(opts...)
	a := NewHTTPAdapter(svc, opts...)
	wrap := func(h http.Handler) http.Handler {
		for i := len(o.Middleware) - 1; i >= 0; i-- {
			h = o.Middleware[i](h)
		}
		// fasthttp would end the process on a panic.
		return httpserver.Recover(h, o.ErrorHandler)
	}
	register := func(app *fiber.App, route func(http.Handler) http.Handler) {
		app.Get("/query", handle(route(http.HandlerFunc(a.QueryStyles))))
		app.Get("/header", handle(route(http.HandlerFunc(a.HeaderStyles))))
		app.Get("/cookie", handle(route(http.HandlerFunc(a.CookieStyles))))
		app.Get("/search", handle(route(http.HandlerFunc(a.Search))))
		app.Get("/path/:simple/:label/:matrix/:list", handle(route(http.HandlerFunc(a.PathStyles))))
	}

	if app, _ := o.Router.(*fiber.App); app != nil {
		register(app, wrap)
		return app
	}
	cfg, _ := o.Router.(fiber.Config)
	answer := cfg.ErrorHandler
	if answer == nil {
		answer = fiber.DefaultErrorHandler
	}
	notFound := handle(wrap(http.NotFoundHandler()))
	methodNotAllowed := handle(wrap(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusMethodNotAllowed)
	})))
	// Answered from the error handler, so that a route added later is still served.
	cfg.ErrorHandler = func(c fiber.Ctx, err error) error {
		var e *fiber.Error
		switch {
		case !errors.As(err, &e):
		case e.Code == fiber.StatusNotFound:
			return notFound(c)
		case e.Code == fiber.StatusMethodNotAllowed:
			return methodNotAllowed(c)
		}
		return answer(c, err)
	}
	app := fiber.New(cfg)
	register(app, wrap)
	return app
}

func handle(h http.Handler) fiber.Handler {
	return func(c fiber.Ctx) error {
		isEscaped := !c.App().Config().UnescapePath
		fasthttpadaptor.NewFastHTTPHandler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// fiber reuses the memory of the request's strings for the next request.
			r = httpserver.DetachRequest(r)
			for _, name := range c.Route().Params {
				if isEscaped {
					r.SetPathValue(name, httpserver.DetachPathValue(c.Params(name)))
				} else {
					r.SetPathValue(name, strings.Clone(c.Params(name)))
				}
			}
			h.ServeHTTP(w, r)
		}))(c.RequestCtx())
		return nil
	}
}
